window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-555297c55922aa5f"]={"versions": [{"id": "FIG-555297c55922aa5f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Gpt_Init()</code>) im Kontext der AUTOSAR-Basissoftware (BSW). Dargestellt ist die Initialisierungsphase des General Purpose Timer Treibers (GPT) durch den ECU State Manager (EcuM) auf Ebene der Mikrocontroller-Abstraktionsschicht (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>EcuM::EcuM</code>: Rufer-Lebenslinie, repräsentiert die Instanz des ECU State Managers.\n</li><li><code>Gpt::Gpt</code>: Ziel-Lebenslinie, repräsentiert die Instanz des GPT-Treibers.\n</li><li>Schnittstellenoperation / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Funktionsaufruf <code>Gpt_Init(configPtr)</code> von <code>EcuM::EcuM</code> an <code>Gpt::Gpt</code>.\n</li><li>Rückkehrnachricht <code>Gpt_Init</code> von <code>Gpt::Gpt</code> an <code>EcuM::EcuM</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> stößt den synchronen Aufruf <code>Gpt_Init(configPtr)</code> an den GPT-Treiber an und aktiviert dessen Ausführungsbalken (Activation Bar).\n</li><li>Der GPT-Treiber führt seine interne Initialisierungsroutine basierend auf der übergebenen Konfigurationsstruktur aus.\n</li><li>Nach Abschluss der Initialisierung kehrt die Ausführung über die gestrichelte Antwortnachricht <code>Gpt_Init</code> zum Aufrufer <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgegebener Ablauf für die BSW-Startphase: Der GPT-Treiber darf erst nach dem Aufruf von <code>Gpt_Init</code> verwendet werden. Der Aufruf muss synchron erfolgen, wobei der Zeiger <code>configPtr</code> auf eine gültige Konfigurationsdatenstruktur verweisen muss.</p>"}, {"id": "FIG-74abc666cedc5e3a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Gpt_Init()</code>) im Kontext der AUTOSAR-Basissoftware (BSW). Dargestellt ist die Initialisierungsphase des General Purpose Timer Treibers (GPT) durch den ECU State Manager (EcuM) auf Ebene der Mikrocontroller-Abstraktionsschicht (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» EcuM::EcuM</code>: Lebenslinie des ECU State Managers, typisiert als Modul.\n</li><li><code>«module» Gpt::Gpt</code>: Lebenslinie des GPT-Treibers, typisiert als Modul.\n</li><li>Schnittstellenoperation / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Funktionsaufruf <code>Gpt_Init(configPtr)</code> von <code>EcuM::EcuM</code> an <code>Gpt::Gpt</code>.\n</li><li>Rückkehrnachricht <code>Gpt_Init</code> von <code>Gpt::Gpt</code> an <code>EcuM::EcuM</code>.\n</li></ul>\n</li><li>Metadaten-Notiz: Status (<code>proposed by TO as per SWS GPT 2.0.0</code>), Beschreibung (<code>Initialisation</code>) und Kommentarfeld.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> stößt den synchronen Aufruf <code>Gpt_Init(configPtr)</code> an den GPT-Treiber an und aktiviert dessen Ausführungsbalken (Activation Bar).\n</li><li>Der GPT-Treiber führt seine interne Initialisierungsroutine basierend auf der übergebenen Konfigurationsstruktur aus.\n</li><li>Nach Abschluss der Initialisierung kehrt die Ausführung über die gestrichelte Antwortnachricht <code>Gpt_Init</code> zum Aufrufer <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgegebener Ablauf für die BSW-Startphase: Der GPT-Treiber darf erst nach dem Aufruf von <code>Gpt_Init</code> verwendet werden. Der Aufruf muss synchron erfolgen, wobei der Zeiger <code>configPtr</code> auf eine gültige Konfigurationsdatenstruktur verweisen muss.</p>"}, {"id": "FIG-70c90847e825cf22", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Gpt_Init()</code>) im Kontext der AUTOSAR-Basissoftware (BSW). Dargestellt ist die Initialisierungsphase des General Purpose Timer Treibers (GPT) durch den ECU State Manager (EcuM) auf Ebene der Mikrocontroller-Abstraktionsschicht (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Lebenslinie des ECU State Managers mit Stereotyp <code>«module»</code>.\n</li><li><code>«module» Gpt</code>: Lebenslinie des GPT-Treibers mit Stereotyp <code>«module»</code>.\n</li><li>Schnittstellenoperation / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Funktionsaufruf <code>Gpt_Init(const Gpt_ConfigType*)</code> von <code>EcuM</code> an <code>Gpt</code>.\n</li><li>Rückkehrnachricht <code>Gpt_Init()</code> von <code>Gpt</code> an <code>EcuM</code>.\n</li></ul>\n</li><li>Metadaten-Notiz: Status (<code>proposed by TO as per SWS GPT 2.0.0</code>), Beschreibung (<code>Initialisation</code>) und Kommentarfeld.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>EcuM</code> stößt den synchronen Aufruf <code>Gpt_Init(const Gpt_ConfigType*)</code> an den GPT-Treiber an und aktiviert dessen Ausführungsbalken.\n</li><li>Der GPT-Treiber führt die Initialisierung anhand der typisierten Konfiguration durch.\n</li><li>Nach Beendigung kehrt die Steuerung über die gestrichelte Rückkehrnachricht <code>Gpt_Init()</code> an den Aufrufer <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgegebene Signatur und Aufrufkonvention der Initialisierungsfunktion: Der Parameter muss explizit als Zeiger auf konstante Konfigurationsdaten des Typs <code>const Gpt_ConfigType*</code> übergeben werden. Die Initialisierung ist zwingend vor allen weiteren Treiberfunktionen auszuführen.</p>"}], "trans": [{"from": "FIG-555297c55922aa5f", "to": "FIG-74abc666cedc5e3a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotyp <code>«module»</code> über den Instanznamen <code>EcuM::EcuM</code> und <code>Gpt::Gpt</code> in den Kopfzeilen der Lebenslinien.\n</li><li>Kommentarfeld unten im Diagramm mit Metadaten: <code>Status: proposed by TO as per SWS GPT 2.0.0</code>, <code>Description: Initialisation</code>, <code>Comments:.</code>.\n</li></ul>"}, {"from": "FIG-74abc666cedc5e3a", "to": "FIG-70c90847e825cf22", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter der synchronen Aufrufnachricht <code>Gpt_Init</code>: Präzisierung von <code>configPtr</code> zu typisiertem Zeiger <code>const Gpt_ConfigType*</code>.\n</li><li>Bezeichnung der Rückkehrnachricht von <code>Gpt_Init</code> zu <code>Gpt_Init()</code> geändert.\n</li><li>Lebenslinienbezeichner von <code>EcuM::EcuM</code> zu <code>EcuM</code> und von <code>Gpt::Gpt</code> zu <code>Gpt</code> vereinfacht.\n</li></ul>"}]};
